			db #00, #00, #66, #66, #66, #3C, #18, #00	; 118 v
			db #00, #00, #C6, #D6, #D6, #FE, #6C, #00	; 119 w
			db #00, #00, #C6, #6C, #38, #6C, #C6, #00	; 120 x
