ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg150:
;## ntc_plat_scroll ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-31 up one, clear row 31
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, ZXN_ROWS - 1
			ld (ntc_cury), a
			ld a, (ntc_scols)
			ld c, a
			ld b, 0					; BC = a row
			ld hl, ZXN_MAP
			add hl, bc
			ld de, ZXN_MAP
			cp 80
			ld bc, (ZXN_ROWS - 1) * 40
			jr nz, ntc_sc_40
			ld bc, (ZXN_ROWS - 1) * 80
ntc_sc_40:
			ldir					; DE = the last row
			ld h, d
			ld l, e
			ld (hl), ' '
			inc de
			ld c, a
			dec c
			ld b, 0
			ldir
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - the whole tilemap spaces, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld hl, ZXN_MAP
			ld de, ZXN_MAP + 1
			ld bc, ZXN_ROWS * 80 - 1
			ld (hl), ' '
			ldir
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

ntc_rg150_e:
			IF ($ < 49152) && (ntc_rg151_e - ntc_rg151 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg151_e - ntc_rg151 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg151_e - ntc_rg151 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg151:
;## ntc_plat_key ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scankey - A = ASCII of a key pressed since the last scan,
; 0 if none
; ------------------------------------------------------------
ntc_plat_scankey:
			ld hl, ntc_kcur
			ld b, #FE				; half row 0 (address line A8 low) ... 7 (A15)
ntc_ks_line:
			ld c, #FE
			in a, (c)
			or #E0					; (bits 5-7: no keys)
			ld (hl), a
			inc hl
			rlc b
			jr c, ntc_ks_line		; (B's 0 bit moves up: done after A15)
			ld a, #FF
			ld (ntc_kidx), a
			ld hl, ntc_kcur
			ld de, ntc_kprev
			ld iy, ntc_kign
			ld bc, #0800			; B = 8 half rows, C = key index (half row * 8 + bit)
ntc_ks_find:
			ld a, (ntc_kidx)
			inc a
			jr nz, ntc_ks_next
			ld a, (hl)
			cpl
			ex de, hl
			and (hl)				; pressed now, released last scan
			ex de, hl
			and (iy+0)				; not Caps Shift / Symbol Shift
			jr z, ntc_ks_next
ntc_ks_bit:
			rrca
			jr c, ntc_ks_got
			inc c
			jr ntc_ks_bit
ntc_ks_got:
			ld a, c
			ld (ntc_kidx), a
ntc_ks_next:
			ld a, c
			and #F8
			add a, 8
			ld c, a
			inc hl
			inc de
			inc iy
			djnz ntc_ks_find
			ld hl, ntc_kcur
			ld de, ntc_kprev
			ld bc, 8
			ldir
			ld a, (ntc_kidx)
			cp #FF
			jr z, ntc_ks_none
			ld e, a
			ld d, 0
			ld hl, ntc_keymapy		; Symbol Shift (half row 7 bit 1) first
			ld a, (ntc_kcur + 7)
			bit 1, a
			jr z, ntc_ks_map
			ld hl, ntc_keymapc		; then Caps Shift (half row 0 bit 0)
			ld a, (ntc_kcur)
			bit 0, a
			jr z, ntc_ks_map
			ld hl, ntc_keymap
ntc_ks_map:
			add hl, de
			ld a, (hl)
			jp (ix)
ntc_ks_none:
			xor a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_getkey - wait for a key press, A = ASCII
; ------------------------------------------------------------
ntc_plat_getkey:
			ld (ntc_klink), ix
ntc_gk_scan:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr nz, ntc_gk_done
			ld a, (ntc_nmode)		; normal mode: interrupts in while waiting
			or a
			jr z, ntc_gk_wait
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_gk_wait:
			ld bc, 7000				; about 6ms between scans at 28MHz (debounce)
ntc_gk_delay:
			dec bc
			ld a, b
			or c
			jr nz, ntc_gk_delay
			di
			ld a, (ntc_nmode)
			or a
			jr z, ntc_gk_scan
			ld sp, (ntc_ip)
			jr ntc_gk_scan
ntc_gk_done:
			ld ix, (ntc_klink)
			jp (ix)

; keys that never count as a press on their own (Caps Shift, Symbol Shift)
ntc_kign:		db #FE, #FF, #FF, #FF, #FF, #FF, #FF, #FD

; half row 0-7, bit 0-4 -> ASCII (0 = nothing); 8 a half row, 5-7 unused
; 0 Caps Z X C V   1 A S D F G   2 Q W E R T   3 1 2 3 4 5
; 4 0 9 8 7 6      5 P O I U Y  6 Enter L K J H   7 Space Symbol M N B
ntc_keymap:
			db 0, "z", "x", "c", "v", 0, 0, 0
			db "a", "s", "d", "f", "g", 0, 0, 0
			db "q", "w", "e", "r", "t", 0, 0, 0
			db "1", "2", "3", "4", "5", 0, 0, 0
			db "0", "9", "8", "7", "6", 0, 0, 0
			db "p", "o", "i", "u", "y", 0, 0, 0
			db 13, "l", "k", "j", "h", 0, 0, 0
			db " ", 0, "m", "n", "b", 0, 0, 0
ntc_keymapc:								; Caps Shift: capitals; + 0 DEL, + Space Break; the cursor
			db 0, "Z", "X", "C", "V", 0, 0, 0		; keys (Caps + 5-8) the CPC firmware's codes: up 240,
			db "A", "S", "D", "F", "G", 0, 0, 0		; down 241, left 242, right 243
			db "Q", "W", "E", "R", "T", 0, 0, 0
			db 0, 0, 0, 0, 242, 0, 0, 0			; (Edit, Caps Lock, True / Inverse Video: nothing), cursor left
			db 127, 0, 243, 240, 241, 0, 0, 0		; (Graphics: nothing), cursor right / up / down
			db "P", "O", "I", "U", "Y", 0, 0, 0
			db 13, "L", "K", "J", "H", 0, 0, 0
			db 27, 0, "M", "N", "B", 0, 0, 0
ntc_keymapy:								; Symbol Shift: the symbols on the keys (+ the 128's ~ | \ { } [ ])
			db 0, ":", 0, "?", "/", 0, 0, 0		; (X: pound)
			db "~", "|", 92, "{", "}", 0, 0, 0
			db 0, 0, 0, "<", ">", 0, 0, 0		; (Q, W, E: <= <> >=)
			db "!", "@", "#", "$", "%", 0, 0, 0
			db "_", ")", "(", 39, "&", 0, 0, 0
			db 34, ";", 0, "]", "[", 0, 0, 0		; (I: copyright)
			db 13, "=", "+", "-", "^", 0, 0, 0
			db " ", 0, ".", ",", "*", 0, 0, 0

ntc_rg151_e:
			IF ($ < 49152) && (ntc_rg152_e - ntc_rg152 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg152_e - ntc_rg152 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg152_e - ntc_rg152 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg152:
;## ntc_plat_irq ntc_plat_data ntc_data ntc_plat_irqh @shared
; ------------------------------------------------------------
; ntc_plat_irqon - put the interrupt handler at #38 (IM 1: the stub set it) and
; start the line interrupt at raster line 0, the ULA's frame interrupt off
; (NextReg #22: bit 2 the ULA's off, bit 1 the line interrupt on, bit 0 the
; line's bit 8; #23 its bits 0-7). The handler moves it on 52 lines each time
; ------------------------------------------------------------
ntc_plat_irqon:
			ld hl, (#0038)
			ld (ntc_irqold), hl
			ld a, (#003A)
			ld (ntc_irqold + 2), a
			ld a, #C3			; jp ntc_irq
			ld (#0038), a
			ld hl, ntc_irq
			ld (#0039), hl
			ld hl, 0
			ld (ntc_zxline), hl
			ld bc, #243B
			ld a, #23
			out (c), a
			inc b
			xor a
			out (c), a
			dec b
			ld a, #22
			out (c), a
			inc b
			ld a, 6
			out (c), a
			ld a, 1
			ld (ntc_irqset), a
			jp (ix)

ntc_rg152_e:
			IF ($ < 49152) && (ntc_rg153_e - ntc_rg153 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg153_e - ntc_rg153 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg153_e - ntc_rg153 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg153:
;## ntc_plat_irqh ntc_plat_data ntc_data @shared
; the handler: runs on the real stack, between keywords. The line interrupt, every 52 raster
; lines - 6 a frame of 312 lines, 300 a second, as the CPC's: counts the ticks and sets the
; next one. The Next's INT is a pulse (32 T at 3.5MHz), not held: a program with interrupts
; off while the line passes (a long stretch between two Frame waits, say) misses that one.
; So the next line is not simply this one + 52: the raster is read (#1E, #1F) and every 52
; line step from the line this interrupt was set for up to the raster now counts as a tick
; (the ones missed included: the clock keeps 300 a second), and the next interrupt is set at
; the step after - never at a line the raster has passed, which would leave the chain dead
; until it came round, or for ever if the program is always off at that line. The step at
; line 0 is a frame's first (ntc_zxvs 1 for the interrupt classes' counting: it is counted
; even when it was missed). AF goes to AF', HL to RAM, the other registers are kept.
ntc_irq:
			ex af, af'
			ld (ntc_irqhl), hl
			push bc
			push de
			ld bc, #243B
ntc_irq_rd:						; DE = the raster line now (#1E bit 8, #1F: read again until bit 8 holds)
			ld a, #1E
			out (c), a
			inc b
			in d, (c)
			dec b
			ld a, #1F
			out (c), a
			inc b
			in e, (c)
			dec b
			ld a, #1E
			out (c), a
			inc b
			in a, (c)
			dec b
			cp d
			jr nz, ntc_irq_rd
			and 1
			ld d, a
			ld hl, (ntc_zxline)		; the line this interrupt was set for
			ld a, h
			or l
			ld a, 0
			jr nz, ntc_irq_nf
			inc a
ntc_irq_nf:
			ld (ntc_zxvs), a		; 1: line 0, a frame's first (so far: a wrap below sets it too)
			ex de, hl				; HL = now, DE = set for
			or a
			sbc hl, de				; HL = now - set for
			jr nc, ntc_irq_fw
			ld bc, 16				; a little before it (the pulse comes as the line before ends): 0
			add hl, bc
			jr c, ntc_irq_z
			ld bc, 312 - 16			; else the raster wrapped: + 312
			add hl, bc
			jr ntc_irq_fw
ntc_irq_z:
			ld hl, 0
ntc_irq_fw:
			ld c, 1					; C = the ticks: 1 + (now - set for) / 52
			ld b, 0					; (BC = 52 * the ticks past the first, the step to the next line)
ntc_irq_dv:
			ld a, l
			sub 52
			ld l, a
			ld a, h
			sbc a, 0
			ld h, a
			jr c, ntc_irq_dd
			inc c
			ld a, c
			cp 7					; (6 at most: a frame)
			jr c, ntc_irq_dv
			dec c
ntc_irq_dd:
			ld a, c
			ld (ntc_irqn), a
			ld hl, (ntc_ticks)
			ld b, 0
			add hl, bc
			ld (ntc_ticks), hl
			ld hl, 0				; the next line: set for + 52 * the ticks (mod 312)
			ld bc, 52
			ld a, (ntc_irqn)
ntc_irq_st:
			add hl, bc
			dec a
			jr nz, ntc_irq_st
			add hl, de
			ld bc, -312
			add hl, bc
			jr c, ntc_irq_wrp		; past the last line (312 and on): wrapped - line 0 was passed
			sbc hl, bc				; (carry clear: back to the line)
			jr ntc_irq_wr
ntc_irq_wrp:
			ld a, (ntc_irqn)		; the wrap: the step at line 0 was one of these ticks, unless it is
			dec a					; the next one (the only tick was the one set for: HL = 0 now)
			jr nz, ntc_irq_wv
			ld a, h
			or l
			jr z, ntc_irq_wr
ntc_irq_wv:
			ld a, 1
			ld (ntc_zxvs), a
ntc_irq_wr:
			ld (ntc_zxline), hl
			ld bc, #243B
			ld a, #23
			out (c), a
			inc b
			out (c), l
			dec b
			ld a, #22
			out (c), a
			inc b
			ld a, h
			or 6					; the ULA's interrupt off, the line interrupt on
			out (c), a
			dec b
			ld a, (ntc_zxsel)		; the NextReg the code it came in on had selected
			out (c), a
			pop de
			pop bc
			ld a, (ntc_hookon)	; an Interrupt hook: run it at the next safe point
			or a
			jr z, ntc_irq_nohook
			ld (ntc_hookpend), a
ntc_irq_nohook:
			ld hl, (ntc_irqv)		; interrupt classes (Option Class Interrupt): count them - once
			ld a, h					; a tick (the missed ones too: the frame's first among them last,
			or l					; so the classes see it in the same order as the ticks came)
			jr z, ntc_irq_nocl
			push bc
			ld a, (ntc_irqn)
			ld b, a
ntc_irq_cl:
			ld c, 0					; C = 1: a frame's first (ntc_isl_tick reads it on zxn)
			dec b
			jr nz, ntc_irq_cl1
			ld a, (ntc_zxvs)
			ld c, a
ntc_irq_cl1:
			inc b
			push bc
			push hl
			call ntc_irq_jp			; (the handler runs on the real stack)
			pop hl
			pop bc
			djnz ntc_irq_cl
			pop bc
ntc_irq_nocl:
			ld hl, (ntc_irqhl)
			ex af, af'
			ei
			reti					; (reti, not ret: with ntc_zxn_inthold the Next's interrupt controller
ntc_irq_jp:						; takes it as the end of the interrupt - in IM 1 the same as ret)
			jp (hl)
ntc_irqn:		db 1			; the ticks this interrupt counted (1-6)

ntc_rg153_e:
			IF ($ < 49152) && (ntc_rg154_e - ntc_rg154 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg154_e - ntc_rg154 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg154_e - ntc_rg154 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg154:
;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - the end: interrupts off, a soft reset (NextReg 2 bit 0) -
; back to NextZXOS (a NEX file has no caller to return to)
; ------------------------------------------------------------
ntc_plat_exit:
			di
			ld bc, #243B
			ld a, #02
			out (c), a
			inc b
			ld a, 1
			out (c), a
ntc_ex_wait:
			jr ntc_ex_wait

ntc_rg154_e:
			IF ($ < 49152) && (ntc_rg155_e - ntc_rg155 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg155_e - ntc_rg155 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg155_e - ntc_rg155 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg155:
;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the program's arrays and the Memory class's heap in
; main memory must not use. ZXN_MEMTOP (the compiler's): #BA00 with the FileSystem or Loader
; class (their DOS area #BA00-#BDFF, then the stack to #C000), #BE00 without (20261118-1). A
; program that runs on over the stack has its arrays in #C000-#FFFF, where the build has
; already checked them against what is there: the top is then #FD00 (the start-up stub).
; (20261118-1: it was #BA00 always, so such a program stopped at its start with GURU 001.)
; Called on the real stack (call / ret).
ntc_plat_memtop:
			IF ntc_free > #C000		; fwdref-ok
			ld hl, #FD00
			ELSE
			ld hl, ZXN_MEMTOP
			ENDIF
			ret


ntc_pgloaded:	db 4		; the pages taken from the start (Loaded n, Option SaveNex, Option Memory Reserve Pages, the program's own: 0 1 2 5): how many, then the pages
			dw 0, 1, 2, 5
ntc_rg155_e:
ntc_end:				; the end of the program (and of its file)
var_chk_want		equ var_chk_got + 2
glyph_20			equ ntc_font + 0		; " "
glyph_28			equ ntc_font + 64		; "("
glyph_29			equ ntc_font + 72		; ")"
glyph_2C			equ ntc_font + 96		; ","
glyph_34			equ ntc_font + 160		; "4"
glyph_3A			equ ntc_font + 208		; ":"
glyph_41			equ ntc_font + 264		; "A"
glyph_42			equ ntc_font + 272		; "B"
glyph_46			equ ntc_font + 304		; "F"
glyph_49			equ ntc_font + 328		; "I"
glyph_4C			equ ntc_font + 352		; "L"
glyph_50			equ ntc_font + 384		; "P"
glyph_56			equ ntc_font + 432		; "V"
glyph_5B			equ ntc_font + 472		; "["
glyph_5D			equ ntc_font + 488		; "]"
glyph_61			equ ntc_font + 520		; "a"
glyph_62			equ ntc_font + 528		; "b"
glyph_64			equ ntc_font + 544		; "d"
glyph_65			equ ntc_font + 552		; "e"
glyph_66			equ ntc_font + 560		; "f"
glyph_69			equ ntc_font + 584		; "i"
glyph_6B			equ ntc_font + 600		; "k"
glyph_6C			equ ntc_font + 608		; "l"
glyph_6F			equ ntc_font + 632		; "o"
glyph_72			equ ntc_font + 656		; "r"
glyph_73			equ ntc_font + 664		; "s"
glyph_74			equ ntc_font + 672		; "t"
glyph_79			equ ntc_font + 712		; "y"
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack #C000 down (the platform's)"
			DISPLAY "NTC memory: Reserved #BE00-#BFFF (platform zxn)"
			DISPLAY "NTC memory: Reserved #FD00-#FFFF (platform zxn)"
			DISPLAY "NTC memory: Reserved #E000-#F3FF (platform zxn (the text screen))"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
			IF (ntc_bssfrom < 49152) && (ntc_bssfrom + ntc_bss_size > 48640)	; fwdref-ok
ntc_bss		equ 49152		; after Option Memory Reserved #BE00-#BFFF
			ELSEIF (ntc_bssfrom < 62464) && (ntc_bssfrom + ntc_bss_size > 57344)	; fwdref-ok
ntc_bss		equ 62464		; after Option Memory Reserved #E000-#F3FF
			ELSEIF (ntc_bssfrom < 65536) && (ntc_bssfrom + ntc_bss_size > 64768)	; fwdref-ok
ntc_bss		equ 65536		; after Option Memory Reserved #FD00-#FFFF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
			ASSERT ntc_bss + ntc_bss_size <= #10000, "out of memory: the arrays (after the last Option Memory Reserved / Paged range) do not fit below #10000"	; fwdref-ok
arr_nums		equ ntc_bss + 0		; 12 bytes
arr_odd		equ ntc_bss + 12		; 8 bytes
arr_words		equ ntc_bss + 20		; 123 bytes
arr_big		equ ntc_bss + 143		; 16 bytes
arr_grid		equ ntc_bss + 159		; 24 bytes
pa_total_a		equ ntc_bss + 183		; 12 bytes
pa_sortup_a		equ ntc_bss + 195		; 12 bytes
pa_lo_a		equ ntc_bss + 207		; 12 bytes
pa_hi_a		equ ntc_bss + 219		; 12 bytes
pa_count_a		equ ntc_bss + 231		; 12 bytes
pa_longest_s		equ ntc_bss + 243		; 12 bytes
pa_shout_s		equ ntc_bss + 255		; 12 bytes
pa_bigsum_v		equ ntc_bss + 267		; 12 bytes
ntc_bss_size	equ 279
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 48640) || (ntc_bss >= 49152), "the program (or its arrays) reaches into the platform's reserved #BE00-#BFFF (platform zxn: Option Memory Available frees it)"
			ASSERT (ntc_free <= 64768) || (ntc_bss >= 65536), "the program (or its arrays) reaches into the platform's reserved #FD00-#FFFF (platform zxn: Option Memory Available frees it)"
			ASSERT (ntc_free <= 57344) || (ntc_bss >= 62464), "the program (or its arrays) reaches into the platform's reserved #E000-#F3FF (platform zxn (the text screen): Option Memory Available frees it)"

; ============================================================
; ZX Spectrum Next: the start stub (bank 5, page 11 at #7E00) and the NEX file
; ============================================================
			IF NTC_PLATRSV == 0		; (with the platform's #BA00-#FFFF Reserved in the map, the build goes round it)
			ASSERT ntc_free <= #BA00, "the program and its arrays must end below #BA00 (the FileSystem class's DOS area is #BA00-#BDFF, the stack #BE00-#BFFF, the screen #C000-#FFFF)"
			ENDIF
			MMU 3, 11			; page 11 (bank 5's second half) at #6000 to assemble the stub
			org #7E00
zxn_boot:
			di
			ld bc, #243B		; NextReg select (#253B: its value)
			ld a, 6			; Peripheral 2: the NMI buttons off (bit 3 Multiface M1, bit 4 DivMMC DRIVE)
			out (c), a
			inc b
			in a, (c)
			and %11100111
			out (c), a
			dec b
; DivMMC: its automatic paging and its entry points stay exactly as NextZXOS left them
; (NextRegs #B8-#BB untouched). Until 20261110-2 the stub cut them to "rst 8 with ROM 3"
; (#B8 = 2, #B9 = 0, #BB = 0): every emulator ran that; four games crashed on a real Next
; at their first esxDOS call, and #BB = 0 also cleared bit 6, the 0x1FF8-0x1FFF exit the DOS
; leaves its memory by - the emulators do not model those registers (ZEsarUX ignores them),
; so nothing here can prove it; the DOS's own setting is the one every working NEX runs
; with. NextZXOS's setting traps rst 8
; (and #0038, #3Dxx, the tape entries) only with ROM 3 paged, which a program never has
; except round an esxDOS call (the FileSystem class, CyborgOS's SD drive: ROM 3 in
; slots 0-1, rst 8, ROM 3 off), so nothing pages DivMMC in by accident
; (no out (#E3): DivMMC's memory is already out when a NEX starts - .nexload leaves it so -
; and writing the port selects its RAM bank 0 and drops MAPRAM, which loses NextZXOS's esxDOS
; state: its file handles are in DivMMC RAM. With it untouched, RST 8 calls work from the program
; (automap on, the ROM in slots 0-1 for the call: CyborgOS's SD drive does that)
			ld a, #8E		; the 128K paging: normal mode, ROM 0 (no change to slots 6-7: bit 3 = 0). NextZXOS's
			out (c), a		; DivMMC entry points (rst 8, #0038, #3Dxx, the tape addresses) trap only with ROM 3
			inc b			; selected: with ROM 0 none can, whatever a slot holds; an esxDOS call selects ROM 3
			xor a			; round its rst 8 and puts ROM 0 back (the FileSystem class, CyborgOS's SD drive)
			out (c), a
			dec b
			ld a, 7			; CPU speed: 28MHz
			out (c), a
			inc b
			ld a, 3
			out (c), a
			dec b
			ld hl, zxn_mmu		; the slots but 3
			ld e, 7
zxn_bmmu:
			ld a, (hl)
			inc hl
			out (c), a
			inc b
			ld a, (hl)
			inc hl
			out (c), a
			dec b
			dec e
			jr nz, zxn_bmmu
			jp zxn_boot2 + #8000	; on in the copy at #E000-#FFFF (page 11 in slot 7)
zxn_boot2:
			ld a, #53			; slot 3: page 3
			out (c), a
			inc b
			ld a, 3
			out (c), a
			ld hl, #C9FB		; #0038: ei, ret until ntc_plat_irqon puts its jump there
			ld (#0038), hl
			im 1
			jp ntc_start
zxn_mmu:	db #50, 0, #51, 1, #52, 2, #54, 4, #55, 5, #56, 10, #57, 11
			SAVENEX OPEN "VBTEST4.NEX", zxn_boot, #BFFE
			SAVENEX CORE 3, 0, 0
			SAVENEX CFG 0
			SAVENEX BANK 5, 2, 0, 1
			SAVENEX CLOSE
